insert into public.blocks (id, needs) values ('R2', array[]::text[]);
insert into public.blocks (id, needs) values ('E1', array[]::text[]);
insert into public.blocks (id, needs) values ('E2', array['E1']::text[]);
insert into public.blocks (id, needs) values ('E3', array['E1']::text[]);
insert into public.blocks (id, needs) values ('E4', array['E2']::text[]);
insert into public.blocks (id, needs) values ('E5', array['E3', 'E4']::text[]);
insert into public.blocks (id, needs) values ('F2', array[]::text[]);
insert into public.items (id, block, demand, options, explain) values ('r2-fizz-01', 'R2', 0, '[{"right":false,"trap":"yes-no-question","b":null,"why":"This asks about the whole world, and you can answer it with just yes or no."},{"right":false,"trap":"yes-no-question","b":null,"why":"This starts with Do, so the answer is just yes or no. Taste tells us little about the issue."},{"right":false,"trap":"vague-question","b":null,"why":"This is one small number from one afternoon. It is too narrow to show the real issue."},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, 'The best question starts with How, names the place, the issue and who is affected, and needs research to answer. Questions that start with Are or Do can be answered with just yes or no.');
insert into public.items (id, block, demand, options, explain) values ('e1-zap-01', 'E1', 0, '[{"right":false,"trap":"vested-interest-missed","b":null,"why":"The advert mentions tests, but companies don''t make adverts to help you pass. What does ZapFizz get?"},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"author-not-checked","b":null,"why":"There is no research in the advert. A drinks company made it, not scientists."},{"right":false,"trap":"author-not-checked","b":null,"why":"The advert says nothing bad about sugar. A company would not warn you about its own drink."}]'::jsonb, 'ZapFizz makes and sells the drink, so the advert''s purpose is to sell. That is why it only shows good things.');
insert into public.items (id, block, demand, options, explain) values ('e1-lina-01', 'E1', 0, '[{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"emotive-hook","b":null,"why":"Water is not in the post. Read to the end: what does she want from you?"},{"right":false,"trap":"emotive-hook","b":null,"why":"Lina never tells you to see a doctor. Read the last line of the post again."},{"right":false,"trap":"author-not-checked","b":null,"why":"The post has no science report. Look at what her link is for."}]'::jsonb, 'The post ends with an advert for her plan. A source that sells something has a reason to exaggerate.');
insert into public.items (id, block, demand, options, explain) values ('e1-report-01', 'E1', 1, '[{"right":false,"trap":"author-not-checked","b":null,"why":"It suggests free water. Would a company that sells sugary drinks ask for that?"},{"right":false,"trap":"author-not-checked","b":null,"why":"A short homework project could not ask 2,400 students. Check the name of who made it."},{"right":false,"trap":"author-not-checked","b":"E1","why":"The report does not sell anything. Check the name of the group that made it."},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, 'The Health Service made it to learn about students'' health. It sells nothing, which is one reason it is more credible.');
insert into public.items (id, block, demand, options, explain) values ('e2-news-01', 'E2', 0, '[{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"author-not-checked","b":null,"why":"Shop owners know about sales, not health. And check the date."},{"right":false,"trap":"old-source","b":null,"why":"The article is about the past. Check when it was written before you say ''now''."},{"right":false,"trap":"old-source","b":null,"why":"Even a checked fact can go out of date. Look at the date on the article."}]'::jsonb, 'Currency is the C in CRAAP. An article from 2009 tells us about the past, not about students today.');
insert into public.items (id, block, demand, options, explain) values ('e2-report-01', 'E2', 1, '[{"right":false,"trap":"emotive-hook","b":null,"why":"A source is not strong just because it agrees with you."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"author-not-checked","b":null,"why":"Easy to read does not mean strong. Think about how much evidence it has and who made it."},{"right":false,"trap":"all-or-nothing","b":null,"why":"Numbers can be wrong or made up. A source is strong because of who made it and how."}]'::jsonb, 'A large survey by a health organisation that explains its method is accurate and has authority. Numbers alone don''t make a source true.');
insert into public.items (id, block, demand, options, explain) values ('e2-nurse-01', 'E2', 2, '[{"right":false,"trap":"all-or-nothing","b":null,"why":"Experts can be wrong too. She says herself that she has not counted carefully."},{"right":false,"trap":"anecdote-as-proof","b":"E1","why":"She sees a lot, but she says she has not counted. Seeing is not the same as measuring."},{"right":false,"trap":"all-or-nothing","b":null,"why":"One person''s view can still be a useful clue. It just needs more evidence with it."},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, 'Good judgements are often ''partly''. Her experience is useful local evidence, but without counting it is not proof.');
insert into public.items (id, block, demand, options, explain) values ('e3-lina-01', 'E3', 0, '[{"right":false,"trap":"emotive-hook","b":null,"why":"This is the name of her product. It is not chosen to stir up your feelings."},{"right":false,"trap":"emotive-hook","b":null,"why":"These words just say what she did. They are calm, not emotional."},{"right":false,"trap":"emotive-hook","b":null,"why":"This just tells you where the link is. It does not try to make you feel anything."},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, 'Words like POISON, capitals and emojis try to scare you. Feelings are not evidence.');
insert into public.items (id, block, demand, options, explain) values ('e3-zap-01', 'E3', 1, '[{"right":false,"trap":"claim-no-evidence","b":null,"why":"The advert does not compare ZapFizz with any other drink."},{"right":false,"trap":"emotive-hook","b":null,"why":"The advert never says how much sugar is in the can."},{"right":false,"trap":"emotive-hook","b":null,"why":"The advert gives no science at all. ''Feel the energy!'' is not evidence."},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, 'It is a feeling, not a fact. Adverts use emotive phrases to make you want the product.');
insert into public.items (id, block, demand, options, explain) values ('e3-study-01', 'E3', 2, '[{"right":false,"trap":"vested-interest-missed","b":"E1","why":"Scientific studies can be biased too. Read the small print."},{"right":false,"trap":"old-source","b":null,"why":"2024 is not very old. The problem is in the small print."},{"right":false,"trap":"small-sample","b":null,"why":"300 people over two years is a fair size. Read the small print instead."},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, 'When the people who pay for research sell the product, they gain from a ''no link'' result. That is a vested interest.');
insert into public.items (id, block, demand, options, explain) values ('e4-zap-01', 'E4', 0, '[{"right":false,"trap":"small-sample","b":null,"why":"We don''t know how many students were asked. 9 out of 10 could mean just 10 students."},{"right":false,"trap":"small-sample","b":null,"why":"The company printed this in its own advert. We can''t check who the students were."},{"right":false,"trap":"claim-no-evidence","b":null,"why":"Taste can matter, but that is not the problem here. Ask how this number was found."},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, '10 students at the company''s own camp is a tiny, chosen group. It tells us almost nothing about all students.');
insert into public.items (id, block, demand, options, explain) values ('e4-compare-01', 'E4', 1, '[{"right":false,"trap":"anecdote-as-proof","b":null,"why":"This is one person''s story, and she is selling something."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"wrong-group","b":null,"why":"This study was about adults, not teens, and a drinks group paid for it."},{"right":false,"trap":"vested-interest-missed","b":null,"why":"A company tested its own drink. It wants to sell, so it is not neutral."}]'::jsonb, 'The survey is large, recent, about teenagers on the island and made by a body that sells nothing.');
insert into public.items (id, block, demand, options, explain) values ('e4-study-01', 'E4', 2, '[{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"all-or-nothing","b":null,"why":"Studies are not always wrong. This one just can''t answer this question."},{"right":false,"trap":"wrong-group","b":null,"why":"It is a lot of people, but check what kind of people they were."},{"right":false,"trap":"all-or-nothing","b":null,"why":"A study only tells you about the people it studied. Check who was in it."}]'::jsonb, 'Evidence about adults may not apply to children, and the funding gives a reason to doubt it.');
insert into public.items (id, block, demand, options, explain) values ('e5-arg-01', 'E5', 0, '[{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"claim-no-evidence","b":null,"why":"Short is easy to remember, but B gives no evidence at all."},{"right":false,"trap":"emotive-hook","b":null,"why":"Sounding sure is not the same as having evidence. ''Everyone knows it'' proves nothing."},{"right":false,"trap":"claim-no-evidence","b":"E4","why":"Wanting the same thing does not make them equal. Look at what each one uses as support."}]'::jsonb, 'A has a claim, a reason and evidence from a credible source. B only has a claim and emotive words.');
insert into public.items (id, block, demand, options, explain) values ('e5-arg-02', 'E5', 1, '[{"right":false,"trap":"claim-no-evidence","b":null,"why":"It does make a claim: ''A ban won''t work.''"},{"right":false,"trap":"claim-no-evidence","b":null,"why":"It does give a reason: students will buy drinks outside school."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"claim-no-evidence","b":null,"why":"A strong argument needs a claim, a reason and one more thing. Which part is missing?"}]'::jsonb, 'Claim: a ban won''t work. Reason: students buy outside. Missing: evidence, such as what happened in other schools.');
insert into public.items (id, block, demand, options, explain) values ('e5-arg-03', 'E5', 2, '[{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"correlation-cause","b":null,"why":"The survey shows a pattern. Does a pattern prove something is the ONLY cause?"},{"right":false,"trap":"old-source","b":null,"why":"2025 is recent. The age of the survey is not the problem."},{"right":false,"trap":"wrong-group","b":null,"why":"The survey asked students aged 11 to 16, not adults."}]'::jsonb, 'Other things, like brushing and sweets, also cause decay. A link shows they happen together, not that one is the only cause.');
insert into public.items (id, block, demand, options, explain) values ('r2-fizz-02', 'R2', 0, '[{"right":false,"trap":"yes-no-question","b":null,"why":"This starts with Is, so it can be answered with just yes or no."},{"right":false,"trap":"yes-no-question","b":null,"why":"This is far too big for one island to research, and it is a yes or no question."},{"right":false,"trap":"vague-question","b":null,"why":"This is too vague. Which people? Which drinks? Where?"},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, '"Why do students on Harvest Key choose sugary drinks?" names the place and the people and needs research. Questions starting with Is or Should can be answered yes or no, and "What do people think about drinks?" is far too broad.');
insert into public.items (id, block, demand, options, explain) values ('r2-fizz-03', 'R2', 1, '[{"right":false,"trap":"yes-no-question","b":null,"why":"It is more focused, but it still starts with Are, so the answer is just yes or no."},{"right":false,"trap":"yes-no-question","b":null,"why":"''Really, really'' and ''the whole world'' make it bigger, not better. It is still yes or no."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"vague-question","b":null,"why":"This is not about the issue at all, and it needs no research."}]'::jsonb, 'Starting with "To what extent" turns a yes/no question into one you must research. Adding detail to a question that starts with Are still leaves a yes/no question.');
insert into public.items (id, block, demand, options, explain) values ('e1-zap-02', 'E1', 1, '[{"right":false,"trap":"author-not-checked","b":null,"why":"Look at the advert''s name. A school did not make it."},{"right":false,"trap":"author-not-checked","b":null,"why":"No doctors are named in the advert. Who is selling the drink?"},{"right":false,"trap":"vested-interest-missed","b":null,"why":"Students did not make this advert. Who makes money if you believe it?"},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, 'ZapFizz Drinks Ltd made it. The more people believe the advert, the more cans they sell, so they have a vested interest.');
insert into public.items (id, block, demand, options, explain) values ('e1-zap-03', 'E1', 2, '[{"right":false,"trap":"vested-interest-missed","b":null,"why":"Adverts can stretch the truth. Being printed does not make it true."},{"right":false,"trap":"small-sample","b":null,"why":"We don''t know who those students were, and liking the taste says nothing about tests."},{"right":false,"trap":"claim-no-evidence","b":null,"why":"Not every fizzy drink makes you sleepy. That is a new claim with no evidence."},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, 'Advice from someone who sells the product needs checking. The advert gives no evidence that the drink helps in tests.');
insert into public.items (id, block, demand, options, explain) values ('e3-lina-02', 'E3', 1, '[{"right":false,"trap":"author-not-checked","b":null,"why":"The post does not mention any doctor."},{"right":false,"trap":"emotive-hook","b":null,"why":"Capital letters do not check anything. Anyone can type in capitals."},{"right":false,"trap":"claim-no-evidence","b":null,"why":"Her post has no scientific results. It is only her own story."},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, 'Capitals make a claim feel exciting. They add no evidence, and she wants you to buy her plan.');
insert into public.items (id, block, demand, options, explain) values ('e3-lina-03', 'E3', 2, '[{"right":false,"trap":"anecdote-as-proof","b":null,"why":"She is selling a plan, so her post is not balanced."},{"right":false,"trap":"author-not-checked","b":null,"why":"Lots of followers does not make someone an expert."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"all-or-nothing","b":null,"why":"Social media can have true facts. We just need to check them."}]'::jsonb, 'The post shows one side, uses fear and capitals, and ends with an advert. Followers are not the same as expertise.');
insert into public.items (id, block, demand, options, explain) values ('e2-news-02', 'E2', 1, '[{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"old-source","b":null,"why":"Facts can change over time. What was true then may not be true now."},{"right":false,"trap":"author-not-checked","b":null,"why":"A big name does not tell you if the facts are still true."},{"right":false,"trap":"claim-no-evidence","b":null,"why":"That would not help you check the article at all."}]'::jsonb, 'Sales change over time. A fact from 2009 may not be true now, so check for something recent.');
insert into public.items (id, block, demand, options, explain) values ('e2-news-03', 'E2', 2, '[{"right":false,"trap":"old-source","b":null,"why":"Another 2009 article is just as old."},{"right":false,"trap":"anecdote-as-proof","b":null,"why":"One person''s memory of 2009 is still old, and it is only one view."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"old-source","b":null,"why":"Sharing an old article again does not make the facts new."}]'::jsonb, 'A report from this year answers a question about now. Re-sharing an old article doesn''t update it.');
insert into public.items (id, block, demand, options, explain) values ('e1-report-02', 'E1', 0, '[{"right":false,"trap":"author-not-checked","b":null,"why":"That is Lina''s product, not the Health Service''s idea."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"author-not-checked","b":null,"why":"A Health Service would not want that. Read the last line of the report."},{"right":false,"trap":"claim-no-evidence","b":null,"why":"The report never says that. Read the last line again."}]'::jsonb, 'The report ends by suggesting free water at school. Its purpose is students'' health, not selling a product.');
insert into public.items (id, block, demand, options, explain) values ('e1-report-03', 'E1', 2, '[{"right":false,"trap":"claim-no-evidence","b":null,"why":"Drinks companies can do surveys. Think about what they would want the results to say."},{"right":false,"trap":"all-or-nothing","b":null,"why":"Health workers can make mistakes too. Think about what each group wants people to believe."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"all-or-nothing","b":null,"why":"A longer report is not always a more careful one."}]'::jsonb, 'The Health Service doesn''t sell drinks, so it has no money reason to want one answer. That is not the same as never making mistakes.');
insert into public.items (id, block, demand, options, explain) values ('e3-study-02', 'E3', 1, '[{"right":false,"trap":"vested-interest-missed","b":null,"why":"Studies cost money, and someone pays. Read the small print."},{"right":false,"trap":"author-not-checked","b":null,"why":"People who take part in a study don''t usually pay for it."},{"right":false,"trap":"author-not-checked","b":null,"why":"Read the small print again. The Health Service did not pay."},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, 'The soft drinks makers paid. Always look for who paid, because they may want a certain result.');
insert into public.items (id, block, demand, options, explain) values ('e3-study-03', 'E3', 2, '[{"right":false,"trap":"all-or-nothing","b":null,"why":"Funding does not make every word false. Ignoring all of it goes too far."},{"right":false,"trap":"wrong-group","b":null,"why":"The study was about adults. It cannot tell us about children."},{"right":false,"trap":"vested-interest-missed","b":null,"why":"Taking a long time does not remove bias. Read the small print."},{"right":true,"trap":null,"b":null,"why":null}]'::jsonb, 'Funding by drink makers is a reason for caution, not proof it is false. Check it against sources with no vested interest.');
insert into public.items (id, block, demand, options, explain) values ('e2-nurse-02', 'E2', 1, '[{"right":false,"trap":"old-source","b":null,"why":"2026 is this year. It is not old."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"all-or-nothing","b":null,"why":"She sees many students in her office, so she does know something."},{"right":false,"trap":"author-not-checked","b":null,"why":"There is no sign that a drinks company pays her."}]'::jsonb, 'She says herself that she hasn''t counted. Her view is useful, but without numbers it is weaker evidence.');
insert into public.items (id, block, demand, options, explain) values ('e2-nurse-03', 'E2', 2, '[{"right":false,"trap":"emotive-hook","b":null,"why":"Saying it with more feeling does not add any evidence."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"anecdote-as-proof","b":null,"why":"One more person''s view is still just a view. It is not counted data."},{"right":false,"trap":"all-or-nothing","b":null,"why":"Ignoring the big survey makes your evidence weaker, not stronger."}]'::jsonb, 'Counting cases over time turns an impression into data. One more story or stronger words would not.');
insert into public.items (id, block, demand, options, explain) values ('e4-compare-02', 'E4', 1, '[{"right":false,"trap":"emotive-hook","b":null,"why":"Exciting is not the same as reliable."},{"right":false,"trap":"author-not-checked","b":null,"why":"Lots of followers does not make a post true."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"all-or-nothing","b":null,"why":"Talking about the same topic does not make two sources equally strong."}]'::jsonb, 'The survey looked at thousands of students. Lina''s post is one person''s story, and she is selling something.');
insert into public.items (id, block, demand, options, explain) values ('e4-compare-03', 'E4', 2, '[{"right":false,"trap":"wrong-group","b":null,"why":"The adult study is not about teens, and a drinks group paid for it."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"anecdote-as-proof","b":null,"why":"The advert comes from a company selling its drink. Should it be in the middle?"},{"right":false,"trap":"vested-interest-missed","b":null,"why":"This list is upside down. Which source has the most and fairest evidence?"}]'::jsonb, 'The survey is large and independent. The nurse is useful but uncounted. The advert has a vested interest and a tiny sample.');
insert into public.items (id, block, demand, options, explain) values ('e5-arg-04', 'E5', 0, '[{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"emotive-hook","b":null,"why":"Funny is not the same as convincing. Look for evidence."},{"right":false,"trap":"claim-no-evidence","b":null,"why":"B is a guess about what students think. It has no evidence."},{"right":false,"trap":"all-or-nothing","b":null,"why":"Water at school matters for health. Compare the support each argument gives."}]'::jsonb, 'A gives a claim, a reason and evidence from a credible source. B is an opinion with no evidence.');
insert into public.items (id, block, demand, options, explain) values ('e5-arg-05', 'E5', 1, '[{"right":false,"trap":"claim-no-evidence","b":null,"why":"Giving energy does not mean healthy. Sugar gives energy too."},{"right":false,"trap":"vested-interest-missed","b":null,"why":"The company wants to sell its drink, so its advert is not neutral evidence."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"all-or-nothing","b":null,"why":"Being about the same drink does not make them equal. Which one uses a fact?"}]'::jsonb, 'B uses a checkable fact. A repeats what the seller says, and the seller gains if you believe it.');
insert into public.items (id, block, demand, options, explain) values ('e5-arg-06', 'E5', 1, '[{"right":false,"trap":"anecdote-as-proof","b":null,"why":"One story is still just one case. It does not show a pattern."},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"all-or-nothing","b":null,"why":"One person''s view, not counted carefully, does not prove anything."},{"right":false,"trap":"emotive-hook","b":null,"why":"Shouting does not add any evidence."}]'::jsonb, 'The nurse''s view is a start. Counted data that links the drinks to headaches would be real evidence.');
insert into public.items (id, block, demand, options, explain) values ('e5-arg-07', 'E5', 2, '[{"right":false,"trap":"all-or-nothing","b":null,"why":"It is not how one person feels. Where does the number come from?"},{"right":true,"trap":null,"b":null,"why":null},{"right":false,"trap":"claim-no-evidence","b":null,"why":"It does not say what anyone should do. It only gives a number."},{"right":false,"trap":"claim-no-evidence","b":null,"why":"It does not use ''because'' or explain why. Look at what kind of sentence it is."}]'::jsonb, 'It is a fact from the Health Service survey, so it is evidence. The claim would be "ban sugary drinks"; a reason would explain why.');
insert into public.trust_cards (idx, ok, trap, why) values (0, true, null, 'Expert author, recent data, no product to sell.');
insert into public.trust_cards (idx, ok, trap, why) values (1, false, 'vested-interest-missed', 'They sell sweets, so they gain if you believe it.');
insert into public.trust_cards (idx, ok, trap, why) values (2, false, 'emotive-hook', 'Shouting and shock words try to make you feel, not think.');
insert into public.trust_cards (idx, ok, trap, why) values (3, false, 'old-source', 'Too old for a question about apps today.');
insert into public.trust_cards (idx, ok, trap, why) values (4, true, null, 'Large sample, expert author, method shown.');
insert into public.trust_cards (idx, ok, trap, why) values (5, false, 'anecdote-as-proof', 'One story is not proof for everyone.');
insert into public.trust_cards (idx, ok, trap, why) values (6, true, null, 'Official, recent, about the whole country.');
insert into public.trust_cards (idx, ok, trap, why) values (7, false, 'small-sample', '8 people at one shop is a tiny, chosen sample.');
insert into public.trust_cards (idx, ok, trap, why) values (8, true, null, 'Named experts and up to date.');
insert into public.trust_cards (idx, ok, trap, why) values (9, false, 'vested-interest-missed', 'The company sells the car.');
insert into public.trust_cards (idx, ok, trap, why) values (10, true, null, 'Primary data from the people who counted it.');
insert into public.trust_cards (idx, ok, trap, why) values (11, false, 'author-not-checked', 'We can''t check who wrote it or when.');
insert into public.trust_cards (idx, ok, trap, why) values (12, true, null, 'Recent records kept by the people who did the counting.');
insert into public.trust_cards (idx, ok, trap, why) values (13, true, null, 'Named experts writing about their own subject.');
insert into public.trust_cards (idx, ok, trap, why) values (14, true, null, 'Official, recent and about the whole country.');
insert into public.trust_cards (idx, ok, trap, why) values (15, true, null, 'Expert authors, and anyone can check the data.');
insert into public.trust_cards (idx, ok, trap, why) values (16, true, null, 'Expert-checked and up to date.');
insert into public.trust_cards (idx, ok, trap, why) values (17, true, null, 'Large sample and an open method.');
insert into public.trust_cards (idx, ok, trap, why) values (18, true, null, 'Checked by experts, and it sells nothing about the topic.');
insert into public.trust_cards (idx, ok, trap, why) values (19, true, null, 'Measured data from the people who collected it.');
insert into public.trust_cards (idx, ok, trap, why) values (20, true, null, 'Expert source, and it is current.');
insert into public.trust_cards (idx, ok, trap, why) values (21, false, 'vested-interest-missed', 'They sell the game, so they gain if you believe it.');
